function color(hex, opacity = 1) {
  const value = hex.replace("#", "");
  return {
    r: parseInt(value.slice(0, 2), 16) / 255,
    g: parseInt(value.slice(2, 4), 16) / 255,
    b: parseInt(value.slice(4, 6), 16) / 255,
    a: opacity,
  };
}

function solid(hex, opacity = 1) {
  return { type: "SOLID", color: color(hex, 1), opacity };
}

function gradient(stops, direction = "vertical") {
  return {
    type: "GRADIENT_LINEAR",
    gradientTransform:
      direction === "horizontal"
        ? [
            [1, 0, 0],
            [0, 1, 0],
          ]
        : [
            [0, 1, 0],
            [1, 0, 0],
          ],
    gradientStops: stops.map(([position, hex, alpha]) => ({
      position,
      color: color(hex, alpha),
    })),
  };
}

function base64Bytes(base64) {
  const alphabet =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const clean = base64.replace(/[^A-Za-z0-9+/=]/g, "");
  const output = [];
  let buffer = 0;
  let bits = 0;
  for (let i = 0; i < clean.length; i += 1) {
    const char = clean[i];
    if (char === "=") break;
    buffer = (buffer << 6) | alphabet.indexOf(char);
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      output.push((buffer >> bits) & 0xff);
    }
  }
  return new Uint8Array(output);
}

function findAvailableFont(available, families, styles) {
  for (const family of families) {
    for (const style of styles) {
      const found = available.find(
        (item) =>
          item.fontName.family === family &&
          item.fontName.style.toLowerCase() === style.toLowerCase(),
      );
      if (found) return found.fontName;
    }
  }
  for (const family of families) {
    const found = available.find((item) => item.fontName.family === family);
    if (found) return found.fontName;
  }
  return null;
}

async function loadFonts() {
  const available = await figma.listAvailableFontsAsync();
  const sansFamilies = [
    "Noto Sans SC",
    "Microsoft YaHei",
    "PingFang SC",
    "Inter",
  ];
  const serifFamilies = [
    "Noto Serif SC",
    "Source Han Serif SC",
    "Songti SC",
    "STSong",
    "SimSun",
  ];

  FONTS.regular = findAvailableFont(available, sansFamilies, [
    "Regular",
    "Normal",
  ]);
  FONTS.medium = findAvailableFont(available, sansFamilies, [
    "Medium",
    "Regular",
  ]);
  FONTS.bold = findAvailableFont(available, sansFamilies, [
    "Semi Bold",
    "SemiBold",
    "Bold",
    "Medium",
    "Regular",
  ]);
  FONTS.serif = findAvailableFont(available, serifFamilies, [
    "Bold",
    "Semi Bold",
    "Medium",
    "Regular",
  ]);

  if (!FONTS.regular) {
    throw new Error("没有可用的中文字体，请先在 Figma 中启用 Noto Sans SC。");
  }
  if (!FONTS.serif) FONTS.serif = FONTS.bold || FONTS.regular;

  const unique = new Map();
  for (const font of Object.values(FONTS)) {
    if (font) unique.set(`${font.family}__${font.style}`, font);
  }
  for (const font of unique.values()) {
    await figma.loadFontAsync(font);
  }
}

async function createImageAssets() {
  for (const [name, base64] of Object.entries(ASSET_BASE64)) {
    IMAGES[name] = figma.createImage(base64Bytes(base64));
  }
}

async function loadBookCoverImages() {
  await Promise.all(BOOK_DATA.books.map(async (book) => {
    const key = `data-book-${book.id}`;
    if (IMAGES[key]) return;
    if (!book.coverUrl) {
      IMAGES[key] = IMAGES["cover-little-prince"];
      return;
    }
    try {
      IMAGES[key] = await figma.createImageAsync(book.coverUrl);
    } catch (error) {
      console.warn(`Failed to load cover for ${book.bookNo}`, error);
      IMAGES[key] = IMAGES["cover-little-prince"];
    }
  }));
}

function append(parent, node) {
  parent.appendChild(node);
  return node;
}

function frame(parent, name, x, y, width, height, fill = C.paper, radius = 0) {
  const node = figma.createFrame();
  node.name = name;
  node.resize(width, height);
  node.fills = fill ? [solid(fill)] : [];
  node.cornerRadius = radius;
  node.clipsContent = true;
  append(parent, node);
  node.x = x;
  node.y = y;
  return node;
}

function rect(
  parent,
  name,
  x,
  y,
  width,
  height,
  fill,
  radius = 0,
  options = {},
) {
  const node = figma.createRectangle();
  node.name = name;
  node.resize(width, height);
  node.fills = Array.isArray(fill) ? fill : fill ? [solid(fill, options.opacity || 1)] : [];
  node.cornerRadius = radius;
  if (options.stroke) {
    node.strokes = [solid(options.stroke, options.strokeOpacity || 1)];
    node.strokeWeight = options.strokeWeight || 1;
    node.strokeAlign = "INSIDE";
  }
  if (options.effects) node.effects = options.effects;
  append(parent, node);
  node.x = x;
  node.y = y;
  return node;
}

function ellipse(parent, name, x, y, width, height, fill, options = {}) {
  const node = figma.createEllipse();
  node.name = name;
  node.resize(width, height);
  node.fills = fill ? [solid(fill, options.opacity || 1)] : [];
  if (options.stroke) {
    node.strokes = [solid(options.stroke, options.strokeOpacity || 1)];
    node.strokeWeight = options.strokeWeight || 1;
  }
  append(parent, node);
  node.x = x;
  node.y = y;
  return node;
}

function circleFrame(parent, name, x, y, size, fill, options = {}) {
  const node = frame(parent, name, x, y, size, size, fill, size / 2);
  if (options.stroke) {
    node.strokes = [solid(options.stroke, options.strokeOpacity || 1)];
    node.strokeWeight = options.strokeWeight || 1;
    node.strokeAlign = "INSIDE";
  }
  return node;
}

function imageRect(
  parent,
  name,
  x,
  y,
  width,
  height,
  asset,
  radius = 0,
  opacity = 1,
) {
  const node = figma.createRectangle();
  node.name = name;
  node.resize(width, height);
  node.cornerRadius = radius;
  node.fills = [
    {
      type: "IMAGE",
      imageHash: IMAGES[asset].hash,
      scaleMode: "FILL",
      opacity,
    },
  ];
  append(parent, node);
  node.x = x;
  node.y = y;
  return node;
}

function text(
  parent,
  value,
  x,
  y,
  width,
  options = {},
) {
  const node = figma.createText();
  node.name = options.name || "Text";
  node.fontName = FONTS[options.weight || "regular"] || FONTS.regular;
  node.characters = value;
  node.fontSize = options.size || 14;
  node.fills = [solid(options.color || C.ink, options.opacity || 1)];
  node.textAlignHorizontal = options.align || "LEFT";
  node.textAlignVertical = options.vertical || "TOP";
  node.letterSpacing = { unit: "PIXELS", value: options.letterSpacing || 0 };
  if (options.lineHeight) {
    node.lineHeight = { unit: "PIXELS", value: options.lineHeight };
  }
  append(parent, node);
  node.resize(width, 8);
  node.textAutoResize = "HEIGHT";
  node.x = x;
  node.y = y;
  return node;
}

function shadow(y = 12, blur = 28, opacity = 0.11) {
  return [
    {
      type: "DROP_SHADOW",
      color: color(C.forest, opacity),
      offset: { x: 0, y },
      radius: blur,
      spread: 0,
      visible: true,
      blendMode: "NORMAL",
    },
  ];
}

