async function getPluginPage(name, index) {
  let page = figma.root.children.find(
    (item) =>
      item.type === "PAGE" &&
      item.getPluginData("zhiya-mobile-plugin") === "v1" &&
      item.name === name,
  );
  if (!page) {
    page = figma.createPage();
    page.name = name;
    page.setPluginData("zhiya-mobile-plugin", "v1");
  }
  await figma.setCurrentPageAsync(page);
  for (const child of [...page.children]) child.remove();
  page.backgrounds = [solid(C.page)];
  try {
    figma.root.insertChild(index, page);
  } catch (_) {
    // Page order is cosmetic; ignoring a rejected move keeps generation resilient.
  }
  return page;
}

function removeDuplicateGeneratedPages() {
  const names = [
    "00 知芽 · 设计规范",
    "01 知芽 · 移动端原型",
    "02 知芽 · 组件与状态",
    "03 知芽 · 原型流程",
    "04 知芽 · 后台管理原型",
  ];
  for (const name of names) {
    const matches = figma.root.children.filter(
      (page) => page.type === "PAGE" && page.name === name,
    );
    if (matches.length <= 1) continue;
    const keep =
      matches.find(
        (page) => page.getPluginData("zhiya-mobile-plugin") === "v1",
      ) || matches[0];
    for (const page of matches) {
      if (page !== keep) page.remove();
    }
  }
}

