function addChip(parent, label, x, y, width, active = false) {
  const fill = active ? C.forest : C.paper;
  const border = active ? null : C.line;
  const chip = frame(parent, `筛选/${label}`, x, y, width, 30, fill, 15);
  if (border) {
    chip.strokes = [solid(border, 0.86)];
    chip.strokeWeight = 1;
    chip.strokeAlign = "INSIDE";
  }
  text(chip, label, 8, 7, width - 16, {
    size: 10,
    color: active ? C.paper : C.forestSoft,
    weight: "medium",
    align: "CENTER",
    lineHeight: 14,
  });
  return chip;
}

