function buildBookDataScreens() {
  const detailsX = 48;
  const detailsY = 4300;
  const gapX = 430;
  const gapY = 930;
  BOOK_DATA.books.forEach((book, index) => {
    const col = index % 4;
    const row = Math.floor(index / 4);
    buildDataBookDetail(
      book,
      detailsX + col * gapX,
      detailsY + row * gapY,
    );
  });

  const readersY = detailsY + Math.ceil(BOOK_DATA.books.length / 4) * gapY + 500;
  const allPages = [];
  for (const book of BOOK_DATA.books) {
    for (const page of book.pages) allPages.push({ book, page });
  }
  allPages.forEach(({ book, page }, index) => {
    const col = index % 4;
    const row = Math.floor(index / 4);
    buildDataBookReader(
      book,
      page,
      detailsX + col * gapX,
      readersY + row * gapY,
    );
  });

  const audioY = readersY + Math.ceil(allPages.length / 4) * gapY + 500;
  BOOK_DATA.books.forEach((book, index) => {
    const col = index % 4;
    const row = Math.floor(index / 4);
    buildDataBookAudio(
      book,
      detailsX + col * gapX,
      audioY + row * gapY,
    );
  });
}

async function buildMobilePages(comps) {
  const page = PAGES.mobile;
  await figma.setCurrentPageAsync(page);
  addTextHeader(
    page,
    "知芽 · 移动端核心流程",
    "390 × 844 · 12 个核心页面 + 20 本绘本数据页 · 生成器 v8",
  );
  const startX = 48;
  const startY = 250;
  const gapX = 430;
  const gapY = 930;
  const frames = {
    home: buildHome(comps, startX, startY),
    library: buildLibrary(comps, startX + gapX, startY),
    detail: buildDetail(comps, startX + gapX * 2, startY),
    reader: buildReader(comps, startX + gapX * 3, startY),
    readerPlaying: buildReaderPlaying(comps, startX, startY + gapY),
    ai: buildAI(comps, startX + gapX, startY + gapY),
    aiAnswer: buildAIAnswer(comps, startX + gapX * 2, startY + gapY),
    summary: buildSummary(comps, startX + gapX * 3, startY + gapY),
    growth: buildGrowth(comps, startX, startY + gapY * 2),
    original: buildOriginal(comps, startX + gapX, startY + gapY * 2),
    originalDraft: buildOriginalDraft(comps, startX + gapX * 2, startY + gapY * 2),
    parent: buildParent(comps, startX + gapX * 3, startY + gapY * 2),
    search: buildDataSearch(comps, startX, startY + gapY * 3),
    shelf: buildDataShelf(comps, startX + gapX, startY + gapY * 3),
  };
  return frames;
}

async function attachFlow(frames) {
  const transitions = {
    home: frames.home,
    library: frames.library,
    detail: frames.detail,
    reader: frames.reader,
    readerPlaying: frames.readerPlaying,
    ai: frames.ai,
    aiAnswer: frames.aiAnswer,
    summary: frames.summary,
    growth: frames.growth,
    original: frames.original,
    originalDraft: frames.originalDraft,
    parent: frames.parent,
    search: frames.search,
    shelf: frames.shelf,
    adminList: frames.adminList,
    adminReview: frames.adminReview,
    adminDashboard: frames.adminDashboard,
    adminKnowledge: frames.adminKnowledge,
    adminPermissions: frames.adminPermissions,
  };
  Object.assign(transitions, BOOK_FRAME_MAP);

  for (const { node, destination } of FLOW_LINKS) {
    const target = transitions[destination];
    if (!target) continue;
    try {
      await node.setReactionsAsync([
        {
          trigger: { type: "ON_CLICK" },
          actions: [
            {
              type: "NODE",
              destinationId: target.id,
              navigation: "NAVIGATE",
              transition: null,
              preserveScrollPosition: false,
            },
          ],
        },
      ]);
    } catch (error) {
      console.warn("Failed to attach reaction", destination, error);
    }
  }

  PAGES.mobile.selection = [frames.home];
}

