function buildFlowPage(frames) {
  const page = PAGES.flow;
  addTextHeader(
    page,
    "知芽 · 核心原型流程",
    "点击页面中的按钮和底部导航即可体验。AI 互动建议作为共读页的状态弹层使用。",
  );

  const nodeData = [
    ["home", "首页", "选择今日共读"],
    ["library", "绘本馆", "按年龄和兴趣选书"],
    ["detail", "绘本详情", "了解推荐理由"],
    ["reader", "亲子共读", "翻页、朗读、提问"],
    ["readerPlaying", "正在朗读", "播放与暂停状态"],
    ["ai", "AI 互动", "情境问题与语音回答"],
    ["aiAnswer", "知芽回答", "答案与继续引导"],
    ["summary", "阅读小结", "反馈与亲子活动"],
    ["growth", "成长记录", "留存阅读轨迹"],
    ["original", "原创故事", "生成并审核家庭绘本"],
    ["originalDraft", "故事草稿", "家长确认与安全检查"],
    ["parent", "家长中心", "孩子档案与儿童模式"],
  ];
  const nodes = {};
  nodeData.forEach(([key, title, body], index) => {
    const col = index % 4;
    const row = Math.floor(index / 4);
    const x = 48 + col * 300;
    const y = 210 + row * 210;
    const card = frame(page, `流程节点/${title}`, x, y, 230, 132, C.paper, 20);
    card.strokes = [solid(C.line, 0.8)];
    card.strokeWeight = 1;
    card.effects = shadow(8, 18, 0.06);
    text(card, `${String(index + 1).padStart(2, "0")}  ${title}`, 18, 18, 190, {
      size: 17,
      color: C.forest,
      weight: "serif",
      lineHeight: 23,
    });
    text(card, body, 18, 58, 190, {
      size: 10,
      color: C.muted,
      lineHeight: 16,
    });
    if (key === "home") {
      pill(card, "起点", 18, 92, 58, C.forest, C.paper, 24);
    }
    nodes[key] = card;
  });

  const links = [
    ["home", "detail"],
    ["library", "detail"],
    ["detail", "reader"],
    ["reader", "readerPlaying"],
    ["readerPlaying", "reader"],
    ["reader", "ai"],
    ["ai", "aiAnswer"],
    ["aiAnswer", "summary"],
    ["summary", "growth"],
    ["original", "originalDraft"],
    ["originalDraft", "parent"],
    ["parent", "growth"],
  ];
  for (const [from, to] of links) {
    try {
      const line = figma.createConnector();
      line.name = `连线/${from}-${to}`;
      line.connectorStart = { endpointNodeId: nodes[from].id, magnet: "AUTO" };
      line.connectorEnd = { endpointNodeId: nodes[to].id, magnet: "AUTO" };
      line.strokes = [solid(C.leaf, 0.7)];
      line.strokeWeight = 1.5;
      page.appendChild(line);
    } catch (_) {
      // Connectors are cosmetic; page links remain usable without them.
    }
  }

  text(
    page,
    "主链路：首页 → 绘本详情 → 亲子共读 → AI 互动 → 阅读小结 → 成长记录。\n副链路：绘本馆用于找书；亲子时光承载活动、共读回忆和原创绘本工坊。",
    48,
    1050,
    1120,
    {
      size: 12,
      color: C.muted,
      lineHeight: 21,
    },
  );
}

