function adminButton(parent, label, x, y, width, variant = "primary") {
  const fill = variant === "primary" ? C.forest : C.paper;
  const color = variant === "primary" ? C.paper : C.forest;
  const button = frame(parent, `后台按钮/${label}`, x, y, width, 38, fill, 12);
  if (variant !== "primary") {
    button.strokes = [solid(C.line, 0.8)];
    button.strokeWeight = 1;
    button.strokeAlign = "INSIDE";
  }
  text(button, label, 10, 11, width - 20, {
    size: 9,
    color,
    weight: "bold",
    align: "CENTER",
    lineHeight: 13,
  });
  return button;
}

