function removeEmptyDefaultPages() {
  const pluginPages = new Set(Object.values(PAGES));
  for (const page of [...figma.root.children]) {
    if (pluginPages.has(page)) continue;
    if (page.children.length > 0) continue;
    if (page.name === "Page 1" || page.name === "页面 1") {
      page.remove();
    }
  }
}

async function attachAdminFlow(frames) {
  const targets = {
    adminDashboard: frames.dashboard,
    adminList: frames.list,
    adminReview: frames.review,
    adminKnowledge: frames.knowledge,
    adminPermissions: frames.permissions,
  };
  const failures = [];
  for (const { node, destination } of FLOW_LINKS) {
    const target = targets[destination];
    if (!target) continue;
    const reaction = {
      trigger: { type: "ON_CLICK" },
      actions: [
        {
          type: "NODE",
          destinationId: target.id,
          navigation: "NAVIGATE",
          transition: null,
          preserveScrollPosition: false,
        },
      ],
    };
    try {
      if (typeof node.setReactionsAsync === "function") {
        await node.setReactionsAsync([reaction]);
      } else {
        node.reactions = [reaction];
      }
    } catch (error) {
      failures.push({
        node: node.name || node.id,
        destination,
        message: error?.message || String(error),
      });
    }
  }
  try {
    PAGES.admin.selection = [frames.dashboard];
  } catch (error) {
    failures.push({
      node: "默认起点",
      destination: "adminDashboard",
      message: error?.message || String(error),
    });
  }
  return failures;
}

async function main() {
  CURRENT_STAGE = "加载页面";
  await figma.loadAllPagesAsync();
  CURRENT_STAGE = "加载字体";
  await loadFonts();
  CURRENT_STAGE = "加载图片资源";
  await createImageAssets();
  CURRENT_STAGE = "创建后台页面";
  PAGES.admin = await getPluginPage("00 知芽 · 后台管理原型", 0);
  removeEmptyDefaultPages();

  CURRENT_STAGE = "构建后台画板";
  const adminFrames = buildAdminPage();
  CURRENT_STAGE = "切换到后台页面";
  await figma.setCurrentPageAsync(PAGES.admin);
  CURRENT_STAGE = "绑定原型交互";
  const interactionFailures = await attachAdminFlow(adminFrames);
  CURRENT_STAGE = "完成";
  figma.viewport.scrollAndZoomIntoView(Object.values(adminFrames));
  if (interactionFailures.length) {
    console.warn("Prototype interaction failures", interactionFailures);
    figma.notify(
      `后台画板已生成，${interactionFailures.length} 个交互未绑定。首个：${interactionFailures[0].node} → ${interactionFailures[0].destination} · ${interactionFailures[0].message}`,
      { timeout: 15000 },
    );
  } else {
    figma.notify("知芽后台管理 Figma 原型已生成，五个页面和交互均已绑定。", {
      timeout: 5000,
    });
  }
  figma.closePlugin();
}

main().catch((error) => {
  console.error(error);
  figma.notify(
    `生成失败：${CURRENT_STAGE} · ${error?.stack || error?.message || String(error)}`,
    { error: true, timeout: 15000 },
  );
  figma.closePlugin();
});
